package com.endpoint.frelog.domain.auth.oauth;
import org.junit.jupiter.api.Test;
import org.springframework.security.oauth2.core.user.*;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class SocialIdentityTest {
 OAuth2User user(Map<String,Object> attributes){var map=new HashMap<>(attributes);map.put("principal","fixture");return new DefaultOAuth2User(List.of(new SimpleGrantedAuthority("ROLE_USER")),map,"principal");}
 @Test void naverProfileIsNestedAndDoesNotClaimEmailVerification(){var identity=SocialIdentity.from("naver",user(Map.of("resultcode","00","response",Map.of("id","CaseSensitive-ID","email","naver@example.invalid","nickname","네이버 별명"))));assertThat(identity.subject()).isEqualTo("CaseSensitive-ID");assertThat(identity.name()).isEqualTo("네이버 별명");assertThat(identity.hasVerifiedEmail()).isFalse();}
 @Test void naverErrorsAndMissingIdAreRejected(){for(var attributes:List.<Map<String,Object>>of(Map.of("resultcode","99","response",Map.of("id","id")),Map.of("resultcode","00","response",Map.of("email","x@example.invalid"))))assertThatThrownBy(()->SocialIdentity.from("naver",user(attributes))).isInstanceOf(org.springframework.security.oauth2.core.OAuth2AuthenticationException.class);}
 @Test void kakaoRequiresBothEmailFlags(){for(boolean valid:new boolean[]{false,true})for(boolean verified:new boolean[]{false,true}){var identity=SocialIdentity.from("kakao",user(Map.of("id",123456789012345678L,"kakao_account",Map.of("email","kakao@example.invalid","is_email_valid",valid,"is_email_verified",verified,"profile",Map.of("nickname","카카오 별명")))));assertThat(identity.subject()).isEqualTo("123456789012345678");assertThat(identity.hasVerifiedEmail()).isEqualTo(valid&&verified);}}
 @Test void kakaoCanCompleteEmailLater(){var identity=SocialIdentity.from("kakao",user(Map.of("id",17L)));assertThat(identity.hasVerifiedEmail()).isFalse();assertThat(identity.withVerifiedEmail("verified@example.invalid").hasVerifiedEmail()).isTrue();}
 @Test void attackerCannotSendUnsupportedProvider(){assertThatThrownBy(()->SocialIdentity.from("unknown",user(Map.of("id","id")))).isInstanceOf(org.springframework.security.oauth2.core.OAuth2AuthenticationException.class);}
 @Test void kakaoOptionalProfileSurvivesEmailConfirmation(){var identity=SocialIdentity.from("kakao",user(Map.of("id",42L,"kakao_account",Map.of("profile",Map.of("nickname","선택 별명","profile_image_url","https://k.kakaocdn.net/photo","is_default_image",false)))));assertThat(identity.name()).isEqualTo("선택 별명");assertThat(identity.withVerifiedEmail("verified@example.invalid").profileImageUrl()).isEqualTo("https://k.kakaocdn.net/photo");}
 @Test void kakaoDeclinedOrDefaultProfileUsesLocalDefaults(){for(boolean needsAgreement:new boolean[]{false,true}){var profile=Map.of("nickname","Default nickname","profile_image_url","https://k.kakaocdn.net/default","is_default_nickname",!needsAgreement,"is_default_image",!needsAgreement);var identity=SocialIdentity.from("kakao",user(Map.of("id",43L,"kakao_account",Map.of("profile_nickname_needs_agreement",needsAgreement,"profile_image_needs_agreement",needsAgreement,"profile",profile))));assertThat(identity.name()).isNull();assertThat(identity.profileImageUrl()).isNull();}}

 @Test void naverPictureAndNicknameSurviveEmailProof(){var identity=SocialIdentity.from("naver",user(Map.of("resultcode","00","response",Map.of("id","naver-photo","nickname","네이버 별명","profile_image","https://phinf.pstatic.net/photo"))));assertThat(identity.name()).isEqualTo("네이버 별명");assertThat(identity.withVerifiedEmail("photo@example.invalid").profileImageUrl()).isEqualTo("https://phinf.pstatic.net/photo");}
 @Test void googleVerifiedPrincipalProvidesDisplayNameAndPicture(){var p=org.mockito.Mockito.mock(org.springframework.security.oauth2.core.oidc.user.OidcUser.class);org.mockito.Mockito.when(p.getEmailVerified()).thenReturn(true);org.mockito.Mockito.when(p.getSubject()).thenReturn("google-photo");org.mockito.Mockito.when(p.getEmail()).thenReturn("google-photo@example.invalid");org.mockito.Mockito.when(p.getFullName()).thenReturn("Google name");org.mockito.Mockito.when(p.getPicture()).thenReturn("https://lh3.googleusercontent.com/photo");var identity=SocialIdentity.from("google",p);assertThat(identity.name()).isEqualTo("Google name");assertThat(identity.profileImageUrl()).isEqualTo("https://lh3.googleusercontent.com/photo");}

}
